#[derive(Debug, PartialEq)]
pub enum Pedido {
    Aberto,
    Fechado(i32),
}

pub fn a_etiqueta_do(pedido: Pedido) -> String {
    match pedido {
        Pedido::Fechado(n) => format!("comanda: {}", n),
        Pedido::Aberto => String::from("sem comanda"),
    }
}

testsCode:
use desafio::a_etiqueta_do;
use desafio::Pedido;

#[test]
fn testa_a_etiqueta_da_comanda_doze() {
    assert_eq!(a_etiqueta_do(Pedido::Fechado(12)), String::from("comanda: 12"));
}

#[test]
fn testa_a_etiqueta_do_pedido_aberto() {
    assert_eq!(a_etiqueta_do(Pedido::Aberto), String::from("sem comanda"));
}
